program.source:
Funcion word <- HowItWent(code Como Entero)
  Definir word Como Cadena;
  Si code = 200 Entonces
    word <- "fine";
  Sino
    word <- "problem";
  FinSi
FinFuncion

Algoritmo ShowStatus
  Definir code Como Entero;
  Leer code;
  Escribir HowItWent(code);
FinAlgoritmo

